\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm,booktabs,array,hyperref,microtype}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newcommand{\orient}{\operatorname{orient}}
\newcommand{\ES}{\operatorname{ES}}
\title{The Erd\H{o}s--Szekeres Cup--Cap Theorem\\and the Happy-End Upper Bound}
\author{Aristotle}
\date{July 24, 2026}
\begin{document}
\maketitle

\begin{abstract}
We give a self-contained development of the cup--cap method for planar point sets. For integers $k,l\ge 2$, every set of more than $\binom{k+l-4}{k-2}$ points in general position contains either a $k$-cup or an $l$-cap. The proof is a double induction based on endpoints of cups, with Pascal's identity controlling cardinality. We then prove that, on a chain with increasing horizontal coordinates, a common orientation for consecutive triples forces the same orientation for every ordered triple. Thus a cup or cap is in convex position, yielding the classical Happy-End upper bound
\[
\ES(n)\le \binom{2n-4}{n-2}+1.
\]
Constructive algorithms, numerical consequences, applications, limitations, and further directions are also discussed.
\end{abstract}

\section{Introduction}
Let $\ES(n)$ be the least integer $N$ such that every $N$-point set in the Euclidean plane in general position contains $n$ points in convex position. General position means that no three points are collinear. A finite set is in convex position when every one of its points is a vertex of its convex hull. The Happy-End Problem asks for the behavior, and when possible the exact value, of $\ES(n)$.

The classical existence argument first orders points by horizontal coordinate, then finds a subsequence bending consistently upward or downward. The asymmetric result permits different target lengths $k$ and $l$ and has threshold
\[
\binom{k+l-4}{k-2}+1.
\]
The proof translates geometry into signs, partitions the set using endpoints of chains, and closes the resulting recurrence with Pascal's identity. We develop that argument and the geometric local-to-global step needed to obtain a convex polygon.

\section{Definitions}
\begin{definition}[Orientation]
For $A=(x_A,y_A)$, $B=(x_B,y_B)$, and $C=(x_C,y_C)$, define
\[
\orient(A,B,C)=(x_B-x_A)(y_C-y_A)-(y_B-y_A)(x_C-x_A).
\]
The triple turns left if this value is positive, right if it is negative, and is collinear if it is zero.
\end{definition}
The determinant is twice the signed area of $ABC$. General position therefore makes every triple a strict left or right turn.

Choose a direction in which all point projections are distinct and rotate it to the horizontal axis. Such a direction exists because a finite set has only finitely many directions perpendicular to a segment joining two points. Write the resulting order as $P_1,\ldots,P_N$ with $x_1<\cdots<x_N$.

\begin{definition}[Cup and cap]
For indices $i_1<\cdots<i_r$, the chain $P_{i_1},\ldots,P_{i_r}$ is an $r$-cup if
\[
\orient(P_{i_j},P_{i_{j+1}},P_{i_{j+2}})>0
\quad(1\le j\le r-2).
\]
It is an $r$-cap if all these inequalities are negative. For $r\le 2$ the condition is vacuous.
\end{definition}

\begin{definition}[Oriented convex position]
A selected set is in convex cup position if every triple, listed from left to right, has positive orientation. It is in convex cap position if every such triple has negative orientation. Either condition places all selected points in convex position.
\end{definition}

The use of consecutive triples in the cup and cap definitions is deliberate: extending a chain creates only one new orientation condition.

\section{Local extension}
\begin{lemma}[Cup extension]
If $P_{i_1},\ldots,P_{i_r}$ is an $r$-cup, $r\ge2$, and $Q$ lies to its right with
\[
\orient(P_{i_{r-1}},P_{i_r},Q)>0,
\]
then appending $Q$ gives an $(r+1)$-cup.
\end{lemma}
\begin{proof}
All previous consecutive triples remain unchanged, and the displayed triple is the only new one. Horizontal order is preserved.
\end{proof}

\begin{lemma}[Cap extension]
If $P_{i_1},\ldots,P_{i_r}$ is an $r$-cap, $r\ge2$, and $C$ lies to its left with
\[
\orient(C,P_{i_1},P_{i_2})<0,
\]
then prepending $C$ gives an $(r+1)$-cap.
\end{lemma}
\begin{proof}
The displayed triple is the only new consecutive triple; all old signs persist.
\end{proof}

\section{Endpoint decomposition and the cup--cap bound}
For a positive integer $r$ and point set $S$, let $E_r(S)$ be the set of points that occur as the rightmost endpoint of an $r$-cup contained in $S$.

\begin{lemma}[Endpoint removal]
The set $S\setminus E_r(S)$ contains no $r$-cup.
\end{lemma}
\begin{proof}
If it contained such a cup, the cup's rightmost point would belong to $E_r(S)$ by definition, contradicting its membership in the complement.
\end{proof}

\begin{lemma}[Endpoint caps force a forbidden extension]
Let $a',b'\ge0$. If $S$ contains neither an $(a'+3)$-cup nor a $(b'+3)$-cap, then $E_{a'+2}(S)$ contains no $(b'+2)$-cap.
\end{lemma}
\begin{proof}
Suppose $Q_1<\cdots<Q_{b'+2}$ is such a cap. Since $Q_1$ is an endpoint, an $(a'+2)$-cup ends there. Let $C$ be the penultimate point of that cup. Then $C<Q_1<Q_2$. General position says that $\orient(C,Q_1,Q_2)$ is nonzero. If it is positive, cup extension appends $Q_2$ and creates an $(a'+3)$-cup. If it is negative, cap extension prepends $C$ and creates a $(b'+3)$-cap. Both alternatives are forbidden.
\end{proof}

\begin{theorem}[Reparametrized cup--cap bound]
Let $a,b\ge0$. If a finite point set $S$ in general position contains no $(a+2)$-cup and no $(b+2)$-cap, then
\[
|S|\le \binom{a+b}{a}.
\]
\end{theorem}
\begin{proof}
Use double induction on $(a,b)$. If $a=0$, absence of a $2$-cup implies $|S|\le1=\binom b0$, since every pair is a $2$-cup. The case $b=0$ is symmetric.

Assume $a,b\ge1$ and put $E=E_{a+1}(S)$. Endpoint removal shows that $S\setminus E$ has no $(a+1)$-cup; as a subset of $S$, it has no $(b+2)$-cap. Hence induction gives
\[
|S\setminus E|\le \binom{a+b-1}{a-1}.
\]
The set $E$ has no $(a+2)$-cup because it is a subset of $S$. The endpoint-extension lemma, with $a'=a-1$ and $b'=b-1$, says that it has no $(b+1)$-cap. Therefore
\[
|E|\le \binom{a+b-1}{a}.
\]
The two sets form a disjoint partition, so Pascal's identity yields
\[
|S|\le \binom{a+b-1}{a-1}+\binom{a+b-1}{a}=\binom{a+b}{a}.
\]
\end{proof}

\begin{theorem}[Cup--Cap Theorem]
For $k,l\ge2$, every set of more than
\[
\binom{k+l-4}{k-2}
\]
points in general position with distinct horizontal coordinates contains a $k$-cup or an $l$-cap.
\end{theorem}
\begin{proof}
Otherwise apply the preceding theorem with $a=k-2$ and $b=l-2$ to obtain the contradictory cardinality bound.
\end{proof}

\begin{corollary}[Diagonal bound]
For $n\ge2$, any set of at least $\binom{2n-4}{n-2}+1$ such points contains an $n$-cup or an $n$-cap.
\end{corollary}
\begin{proof}
Set $k=l=n$ in the Cup--Cap Theorem.
\end{proof}

\section{Local turns imply global convexity}
For $x_A<x_B$, define $m(A,B)=(y_B-y_A)/(x_B-x_A)$. If $x_A<x_B<x_C$, direct rearrangement gives
\[
\orient(A,B,C)>0\iff m(A,B)<m(B,C),
\]
with the reversed inequality in the negative case.

\begin{lemma}[Four-point propagation]
Let $x_A<x_B<x_C<x_D$. If $ABC$ and $BCD$ both turn left, then $ABD$ and $ACD$ turn left. If the two given turns are right turns, then the two conclusions are right turns.
\end{lemma}
\begin{proof}
In the positive case,
\[
m(A,B)<m(B,C)<m(C,D).
\]
The slope $m(A,C)$ is a positive weighted average of the first two consecutive slopes, and $m(B,D)$ is a positive weighted average of the last two. Consequently $m(A,B)<m(B,D)$ and $m(A,C)<m(C,D)$, which are the desired orientation statements. Reverse every inequality for caps.
\end{proof}

\begin{theorem}[Local-to-Global Convexity]
Let $P_1,\ldots,P_r$ have strictly increasing horizontal coordinates. If every consecutive triple turns left, every triple $P_i,P_j,P_k$ with $i<j<k$ turns left. If every consecutive triple turns right, every ordered triple turns right.
\end{theorem}
\begin{proof}
Induct on $r$. Removing the first point gives the assertion for triples avoiding it. For triples containing the first point, repeatedly apply four-point propagation: first extend the orientation from the first edge to form a fan, then collapse intermediate vertices until the desired pair of later indices remains. The negative case is identical with signs reversed.
\end{proof}

\begin{corollary}
The points of every cup or cap are in convex position.
\end{corollary}
\begin{proof}
The theorem gives a common strict orientation to all ordered triples. Hence no selected point lies in the convex hull of the others; closing the monotone chain by the segment joining its extremes gives a strictly convex polygon with precisely the selected vertices.
\end{proof}

\section{The Happy-End theorem}
\begin{theorem}[Happy-End upper bound]
For every integer $n\ge2$, every set of at least
\[
\binom{2n-4}{n-2}+1
\]
points in the plane in general position contains $n$ points in convex position.
\end{theorem}
\begin{proof}
Choose a projection direction giving distinct values, rotate it to horizontal, and sort the points. The diagonal cup--cap bound supplies an $n$-cup or $n$-cap. Local-to-global convexity places its points in convex position. Rotation back preserves convexity.
\end{proof}

Thus $\ES(n)\le\binom{2n-4}{n-2}+1$. This is a sufficient threshold, not generally the exact minimum. For example:
\begin{center}
\begin{tabular}{@{}ccc@{}}
\toprule
$n$ & classical guarantee & exact $\ES(n)$ where stated\\
\midrule
$3$ & $3$ & $3$\\
$4$ & $7$ & $5$\\
$5$ & $21$ & $9$\\
$6$ & $71$ & $17$\\
\bottomrule
\end{tabular}
\end{center}
The asymptotic relation
\[
\binom{2n-4}{n-2}\sim \frac{4^{n-2}}{\sqrt{\pi(n-2)}}
\]
shows the exponential scale of this classical bound.

\section{Algorithms}
The diagonal guarantee is computed as $G(n)=\binom{2n-4}{n-2}+1$, while the asymmetric threshold is $G(k,l)=\binom{k+l-4}{k-2}+1$. A multiplicative binomial routine takes $O(\min\{r,s\})$ exact-integer arithmetic operations for $\binom rs$ after symmetry reduction.

An explicit chain can be found by dynamic programming. Sort $N$ points by horizontal coordinate. For every $i<j$, initialize $U[i,j]=D[i,j]=2$, where $U$ and $D$ are the longest cup and cap ending at $(P_i,P_j)$. For each $h<i<j$, update
\[
U[i,j]\leftarrow\max\{U[i,j],U[h,i]+1\}
\]
when $\orient(P_h,P_i,P_j)>0$, and update
\[
D[i,j]\leftarrow\max\{D[i,j],D[h,i]+1\}
\]
when the orientation is negative. Predecessor pointers reconstruct a witness. The sorting step costs $O(N\log N)$ time. The dynamic program costs $O(N^3)$ time and uses $O(N^2)$ memory.

A proposed chain can be checked in linear time by testing horizontal order and its consecutive triples. The local-to-global theorem guarantees that this local test suffices for oriented convex position. Directly checking all triples would instead require $O(r^3)$ orientation evaluations.

\section{Applications, scope, and limitations}
The orientation determinant is fundamental in convex-hull construction, polygon winding, geographic information systems, and planar motion planning. The cup--cap theorem gives it an extremal interpretation: enough nondegenerate planar samples force a long coherently curved subsequence.

The endpoint partition is also a form of state compression. It records not the history of every cup, but only whether a point can end one of a specified length. The complement destroys that cup length, while the endpoint set cannot support too long an opposing cap. This exactly matches the two predecessor terms in Pascal's recurrence, just as $\binom{a+b}{a}$ counts monotone lattice paths to $(a,b)$.

Distinct horizontal coordinates are a coordinate convenience rather than an intrinsic restriction, because generic projection removes ties. Numerical implementations nevertheless require care: floating-point orientation values near zero can be misclassified. Exact integer or rational arithmetic, or robust adaptive predicates, should be used when degeneracy is possible.

The argument proves an upper bound. It neither proves the exact value of $\ES(n)$ for general $n$ nor supplies the separate construction showing that the asymmetric cup--cap threshold is sharp. Sampling configurations can illustrate the theorem but cannot establish its universal quantifier.

\section{Future directions}
A complementary goal is the lower construction
\[
\ES(n)\ge 2^{n-2}+1,
\]
which would give a two-sided framework. Exact small values $\ES(4)=5$, $\ES(5)=9$, and $\ES(6)=17$ invite explicit certificates and exhaustive searches. For the asymmetric theorem, one may construct $\binom{k+l-4}{k-2}$ points with neither a $k$-cup nor an $l$-cap, proving sharpness.

Further geometric work includes relating the common-orientation condition directly to convex hulls and making generic rotation explicit. Sharper upper bounds require more structure than the elementary diagonal argument. Higher-dimensional convex-position problems, positive-fraction variants, partition phenomena, and empty convex polygons provide additional directions.

\section{Conclusion}
General position turns triples into binary left-or-right decisions. Cups and caps encode local curvature. Endpoint marking divides an extremal point set into two recursively controlled parts, and Pascal's identity counts them. Horizontal order then propagates consecutive signs to all triples, converting a chain into a convex polygon. Together these ideas prove that $\binom{2n-4}{n-2}+1$ points in general position always contain $n$ points in convex position.

\end{document}

