class Point(NamedTuple): x:int; y:int
def orient(a:Point,b:Point,c:Point)->int:
    return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x)
def longest(p:list[Point])->tuple[int,int]:
    p=sorted(p); n=len(p)
    if n<2:return n,n
    u=[[2 if i<j else 0 for j in range(n)] for i in range(n)]
    d=[[2 if i<j else 0 for j in range(n)] for i in range(n)]
    for j in range(n):
      for i in range(j):
       for h in range(i):
        z=orient(p[h],p[i],p[j])
        if z>0:u[i][j]=max(u[i][j],u[h][i]+1)
        elif z<0:d[i][j]=max(d[i][j],d[h][i]+1)
    return max(map(max,u)),max(map(max,d))
